  1	//! The one contract for interactive prompts: where they may run, how they end, and how `$EDITOR` is used.
  2	
  3	use std::io::IsTerminal as _;
  4	
  5	use inquire::validator::Validation;
  6	use inquire::Text;
  7	
  8	use crate::cli::OutputFormat;
  9	use crate::error::CliError;
 10	
 11	/// Proof that this run may prompt; only [`Prompts::detect`] makes one.
 12	pub struct Prompts(());
 13	
 14	impl Prompts {
 15	    /// Prompts need a person at the terminal (stdin, and stderr where they draw) and a text run: `--format json` is for
 16	    /// scripts and never prompts.
 17	    pub fn detect(format: OutputFormat) -> Option<Self> {
 18	        (format == OutputFormat::Text && std::io::stdin().is_terminal() && std::io::stderr().is_terminal())
 19	            .then_some(Self(()))
 20	    }
 21	
 22	    #[cfg(test)]
 23	    pub fn for_tests() -> Self {
 24	        Self(())
 25	    }
 26	}
 27	
 28	/// Printed whenever a prompt run ends without writing.
 29	pub const CANCELLED: &str = "Cancelled, nothing written.";
 30	
 31	/// Exit status for a prompt cancelled with Esc or Ctrl-C: 130, as shells report SIGINT.
 32	pub const CANCELLED_EXIT: u8 = 130;
 33	
 34	/// A package in a list: the name the list shows, and its `ecosystem/name` id, which is also accepted when typed.
 35	#[derive(Clone, Debug, PartialEq, Eq)]
 36	pub(crate) struct Listed {
 37	    pub name: String,
 38	    pub id: String,
 39	}
 40	
 41	impl Listed {
 42	    /// An entry shown by its id.
 43	    pub fn by_id(id: &str) -> Self {
 44	        Self {
 45	            name: id.to_owned(),
 46	            id: id.to_owned(),
 47	        }
 48	    }
 49	}
 50	
 51	/// Asks which of `items` to pick, as `git add -i` does: the list is printed once, numbered, with `marked` ones starred,
 52	/// then one typed line answers. Nothing is redrawn, so no terminal size or resize can misdraw it. Enter keeps the marked
 53	/// ones (and, when `empty_ok`, picks none if none is marked); an answer that names nothing listed is asked again with
 54	/// the reason.
 55	pub(crate) fn pick_many(
 56	    heading: &str,
 57	    items: &[Listed],
 58	    marked: &[bool],
 59	    empty_ok: bool,
 60	) -> Result<Vec<usize>, CliError> {
 61	    print_list(heading, items, marked);
 62	    if marked.contains(&true) {
 63	        eprintln!("Enter keeps the * ones, or type numbers, ranges (1-3) or names; Esc cancels.");
 64	    } else if empty_ok {
 65	        eprintln!("Enter picks none, or type numbers, ranges (1-3) or names; Esc cancels.");
 66	    } else {
 67	        eprintln!("Type numbers, ranges (1-3) or names; Esc cancels.");
 68	    }
 69	    read_answer(items, marked, false)
 70	}
 71	
 72	/// Asks for exactly one of `ids`, the way [`pick_many`] asks for several.
 73	pub(crate) fn pick_one(heading: &str, ids: &[String]) -> Result<usize, CliError> {
 74	    let items: Vec<Listed> = ids.iter().map(|id| Listed::by_id(id)).collect();
 75	    print_list(heading, &items, &[]);
 76	    eprintln!("Type a number or a name; Esc cancels.");
 77	    let picked = read_answer(&items, &[], true)?;
 78	    Ok(*picked
 79	        .first()
 80	        .expect("the validator accepts only an answer naming exactly one entry"))
 81	}
 82	
 83	fn print_list(heading: &str, items: &[Listed], marked: &[bool]) {
 84	    let width = items.len().to_string().len();
 85	    let mut text = format!("{heading}\n");
 86	    for (index, item) in items.iter().enumerate() {
 87	        let mark = if marked.get(index) == Some(&true) { '*' } else { ' ' };
 88	        // A control character in a manifest's name must not drive the terminal.
 89	        text.push_str(&format!(
 90	            "  {:>width$} {mark} {}\n",
 91	            index + 1,
 92	            item.name.escape_debug()
 93	        ));
 94	    }
 95	    eprint!("{text}");
 96	}
 97	
 98	/// One line typed at a single-line prompt; the prompt's validator asks again with the reason until [`answer`] accepts
 99	/// it, and Esc or Ctrl-C is [`CliError::Cancelled`].
100	fn read_answer(items: &[Listed], marked: &[bool], one: bool) -> Result<Vec<usize>, CliError> {
101	    let (valid_items, valid_marked) = (items.to_vec(), marked.to_vec());
102	    let line = Text::new("Your answer")
103	        .with_validator(move |line: &str| {
104	            Ok(match answer(line, &valid_items, &valid_marked, one) {
105	                Ok(_) => Validation::Valid,
106	                Err(reason) => Validation::Invalid(reason.into()),
107	            })
108	        })
109	        .prompt()?;
110	    Ok(answer(&line, items, marked, one).expect("the validator accepted this line"))
111	}
112	
113	/// The listed indices a typed line picks: the `marked` ones for an empty line (when several may be picked), else the
114	/// ones [`choices`] names; `one` requires exactly one.
115	fn answer(line: &str, items: &[Listed], marked: &[bool], one: bool) -> Result<Vec<usize>, String> {
116	    let picked = match (line.trim().is_empty(), one) {
117	        (true, false) => (0..items.len())
118	            .filter(|&index| marked.get(index) == Some(&true))
119	            .collect(),
120	        (true, true) => Vec::new(),
121	        (false, _) => choices(line, items)?,
122	    };
123	    if one && picked.len() != 1 {
124	        return Err("pick exactly one".to_owned());
125	    }
126	    Ok(picked)
127	}
128	
129	/// The listed indices an answer names, in list order. A word is a number or range counted from 1 (`3`, `1-3`) when
130	/// those rows exist, else a listed name or `ecosystem/name` id; `#3` or `#1-3` always means rows. Words are separated
131	/// by spaces or commas, and an answer must name at least one.
132	fn choices(answer: &str, items: &[Listed]) -> Result<Vec<usize>, String> {
133	    let mut picked = std::collections::BTreeSet::new();
134	    let mut words = 0;
135	    for word in answer
136	        .split(|c: char| c == ',' || c.is_whitespace())
137	        .filter(|word| !word.is_empty())
138	    {
139	        words += 1;
140	        let shown = word.escape_debug();
141	        if let Some(rows) = word.strip_prefix('#') {
142	            match numbered(rows, items.len()) {
143	                Some(range) => picked.extend(range?),
144	                None => return Err(format!("`{shown}` is not a row number or range")),
145	            }
146	            continue;
147	        }
148	        let by_name = items.iter().position(|item| item.name == word || item.id == word);
149	        let indices = match (by_name, numbered(word, items.len())) {
150	            (Some(index), None | Some(Err(_))) => index..=index,
151	            (Some(index), Some(Ok(range))) if range == (index..=index) => range,
152	            (Some(index), Some(Ok(range))) => {
153	                let rows = match (range.start(), range.end()) {
154	                    (first, last) if first == last => format!("#{}", first + 1),
155	                    (first, last) => format!("#{}-{}", first + 1, last + 1),
156	                };
157	                let id = &items[index].id;
158	                let package = if id == word {
159	                    format!("#{}", index + 1)
160	                } else {
161	                    id.escape_debug().to_string()
162	                };
163	                return Err(format!(
164	                    "`{shown}` is both a package name and a row number; type `{package}` for the package or `{rows}` for the row"
165	                ));
166	            }
167	            (None, Some(range)) => range?,
168	            (None, None) => return Err(format!("`{shown}` is not a number, a range or a listed name")),
169	        };
170	        picked.extend(indices);
171	    }
172	    if words == 0 {
173	        return Err("type at least one number, range or name".to_owned());
174	    }
175	    Ok(picked.into_iter().collect())
176	}
177	
178	/// `n` or `a-b`, counted from 1, as indices; `None` when the word is shaped like neither, `Some(Err)` when the rows are
179	/// not in the list.
180	fn numbered(word: &str, len: usize) -> Option<Result<std::ops::RangeInclusive<usize>, String>> {
181	    let (first, last) = word.split_once('-').unwrap_or((word, word));
182	    let digits = |text: &str| !text.is_empty() && text.bytes().all(|byte| byte.is_ascii_digit());
183	    if !digits(first) || !digits(last) {
184	        return None;
185	    }
186	    let listed = |text: &str| text.parse::<usize>().ok().filter(|number| (1..=len).contains(number));
187	    Some(match (listed(first), listed(last)) {
188	        (Some(low), Some(high)) if low <= high => Ok(low - 1..=high - 1),
189	        (Some(_), Some(_)) => Err(format!("`{word}` runs backwards; put the lower number first")),
190	        _ => Err(format!("`{word}` is not in the list (1-{len})")),
191	    })
192	}
193	
194	/// The editor named by `$VISUAL`, else `$EDITOR`.
195	pub struct Editor {
196	    variable: &'static str,
197	    command: String,
198	}
199	
200	/// Why the editor could not be used; its message is the warning to print.
201	#[derive(Debug, thiserror::Error)]
202	#[error("cannot use ${variable} (`{command}`): {reason}; asking for the summary here instead")]
203	pub struct EditorUnusable {
204	    variable: &'static str,
205	    command: String,
206	    reason: String,
207	}
208	
209	impl Editor {
210	    /// An empty or blank setting is unset.
211	    pub fn from_env() -> Option<Self> {
212	        ["VISUAL", "EDITOR"].into_iter().find_map(|variable| {
213	            let command = std::env::var(variable).ok()?;
214	            (!command.trim().is_empty()).then_some(Self { variable, command })
215	        })
216	    }
217	
218	    /// `VISUAL` or `EDITOR`, whichever named it.
219	    pub fn variable(&self) -> &'static str {
220	        self.variable
221	    }
222	
223	    /// Opens the editor on an empty file and returns what was saved. `None` when the editor exits non-zero (an abort,
224	    /// as `:cq` in Vim). The editor draws on stderr so stdout stays for the report.
225	    pub fn edit(self) -> Result<Option<String>, EditorUnusable> {
226	        self.try_edit().map_err(|reason| EditorUnusable {
227	            variable: self.variable,
228	            command: self.command,
229	            reason,
230	        })
231	    }
232	
233	    fn try_edit(&self) -> Result<Option<String>, String> {
234	        let words = editor_words(&self.command, cfg!(windows))?;
235	        let Some((program, args)) = words.split_first() else {
236	            return Err("it names no program".to_owned());
237	        };
238	        let failed = |error: std::io::Error| error.to_string();
239	        let file = tempfile::Builder::new()
240	            .prefix("callisto-")
241	            .suffix(".txt")
242	            .tempfile()
243	            .map_err(failed)?;
244	        let _editor_owns_ctrl_c = editor_owns_ctrl_c::enter().map_err(failed)?;
245	        let status = crate::runner::child_command(program, &[], &[])
246	            .args(args)
247	            .arg(file.path())
248	            .stdout(std::io::stderr())
249	            .status()
250	            .map_err(|error| format!("`{program}` did not start: {error}"))?;
251	        if !status.success() {
252	            return Ok(None);
253	        }
254	        let saved = std::fs::read(file.path()).map_err(failed)?;
255	        String::from_utf8(saved)
256	            .map(Some)
257	            .map_err(|error| format!("what it saved is not UTF-8 text: {}", error.utf8_error()))
258	    }
259	}
260	
261	/// The program and arguments an editor setting names. Unix settings follow shell quoting; Windows paths use
262	/// backslashes as separators, so there a setting splits on whitespace outside double quotes and keeps every backslash.
263	fn editor_words(command: &str, windows: bool) -> Result<Vec<String>, String> {
264	    if !windows {
265	        return shell_words::split(command).map_err(|error| format!("it does not split into words: {error}"));
266	    }
267	    let mut words = Vec::new();
268	    let (mut word, mut quoted, mut started) = (String::new(), false, false);
269	    for c in command.chars() {
270	        match c {
271	            '"' => (quoted, started) = (!quoted, true),
272	            c if c.is_whitespace() && !quoted => {
273	                if started {
274	                    words.push(std::mem::take(&mut word));
275	                }
276	                started = false;
277	            }
278	            c => {
279	                word.push(c);
280	                started = true;
281	            }
282	        }
283	    }
284	    if quoted {
285	        return Err("it does not split into words: a double quote is not closed".to_owned());
286	    }
287	    if started {
288	        words.push(word);
289	    }
290	    Ok(words)
291	}
