293	#[cfg(unix)]
294	mod editor_owns_ctrl_c {
295	    use std::sync::atomic::{AtomicBool, Ordering};
296	    use std::sync::Arc;
297	
298	    use signal_hook::consts::SIGINT;
299	
300	    /// Ctrl-C in a line-mode editor reaches this process too: as Git's `launch_editor` does, ignore SIGINT while the
301	    /// editor runs and let its exit status decide. Dropping this gives SIGINT its default action back.
302	    pub struct Guard(Arc<AtomicBool>);
303	
304	    pub fn enter() -> std::io::Result<Guard> {
305	        let default_action = Arc::new(AtomicBool::new(false));
306	        signal_hook::flag::register_conditional_default(SIGINT, Arc::clone(&default_action))?;
307	        Ok(Guard(default_action))
308	    }
309	
310	    impl Drop for Guard {
311	        fn drop(&mut self) {
312	            self.0.store(true, Ordering::SeqCst);
313	        }
314	    }
315	}
316	
317	#[cfg(not(unix))]
318	mod editor_owns_ctrl_c {
319	    pub struct Guard;
320	
321	    pub fn enter() -> std::io::Result<Guard> {
322	        Ok(Guard)
323	    }
324	}
