326	#[cfg(test)]
327	mod tests {
328	    use super::{answer, choices, editor_words, Listed};
329	
330	    fn names(names: &[&str]) -> Vec<Listed> {
331	        names.iter().map(|name| Listed::by_id(name)).collect()
332	    }
333	
334	    /// npm packages shown by their bare names.
335	    fn npm(names: &[&str]) -> Vec<Listed> {
336	        names
337	            .iter()
338	            .map(|name| Listed {
339	                name: (*name).to_owned(),
340	                id: format!("npm/{name}"),
341	            })
342	            .collect()
343	    }
344	
345	    #[test]
346	    fn an_answer_picks_by_number_range_and_name_in_list_order() {
347	        let listed = names(&["a", "b", "c", "d", "cargo/e"]);
348	        assert_eq!(choices("3, 1", &listed), Ok(vec![0, 2]));
349	        assert_eq!(choices("2-4", &listed), Ok(vec![1, 2, 3]));
350	        assert_eq!(choices("cargo/e a 1", &listed), Ok(vec![0, 4]));
351	        assert_eq!(choices("1-1,,  b", &listed), Ok(vec![0, 1]));
352	    }
353	
354	    #[test]
355	    fn an_answer_naming_nothing_listed_says_why() {
356	        let listed = names(&["a", "b", "c"]);
357	        for (answer, reason) in [
358	            ("0", "`0` is not in the list (1-3)"),
359	            ("4", "`4` is not in the list (1-3)"),
360	            ("2-9", "`2-9` is not in the list (1-3)"),
361	            ("99999999999999999999999", "is not in the list (1-3)"),
362	            ("3-1", "`3-1` runs backwards"),
363	            ("x", "`x` is not a number, a range or a listed name"),
364	            ("1-", "`1-` is not a number"),
365	            ("-1", "`-1` is not a number"),
366	            ("A", "`A` is not a number"),
367	        ] {
368	            let error = choices(answer, &listed).expect_err(answer);
369	            assert!(error.contains(reason), "{answer}: {error}");
370	        }
371	    }
372	
373	    #[test]
374	    fn a_name_that_reads_as_another_entrys_number_is_refused() {
375	        let ambiguous = "is both a package name and a row number";
376	        let refused = choices("2", &names(&["2", "b"])).unwrap_err();
377	        assert!(refused.contains(ambiguous));
378	        // Without a distinct qualified id the way out is the package's own row, never the word just typed.
379	        assert!(
380	            refused.contains("type `#1` for the package or `#2` for the row"),
381	            "{refused}"
382	        );
383	        assert!(choices("1-2", &names(&["a", "b", "1-2"]))
384	            .unwrap_err()
385	            .contains(ambiguous));
386	        // A name that is its own number is not ambiguous.
387	        assert_eq!(choices("1", &names(&["1", "b"])), Ok(vec![0]));
388	    }
389	
390	    #[test]
391	    fn a_hash_always_means_rows_so_every_suggestion_is_unambiguous() {
392	        let items = names(&["a", "b", "1-1"]);
393	        assert_eq!(choices("#1", &items), Ok(vec![0]));
394	        assert_eq!(choices("#1-2", &items), Ok(vec![0, 1]));
395	        assert_eq!(choices("#3", &items), Ok(vec![2]));
396	        let refused = choices("1-1", &items).unwrap_err();
397	        assert!(
398	            refused.contains("type `#3` for the package or `#1` for the row"),
399	            "{refused}"
400	        );
401	        assert!(choices("#x", &items).unwrap_err().contains("not a row number or range"));
402	        assert!(choices("#9", &items).is_err());
403	    }
404	
405	    #[test]
406	    fn an_answer_of_only_separators_is_asked_again() {
407	        let items = names(&["a", "b"]);
408	        assert_eq!(
409	            choices(",, ,", &items),
410	            Err("type at least one number, range or name".to_owned())
411	        );
412	    }
413	
414	    #[test]
415	    fn windows_editor_settings_keep_backslashes() {
416	        assert_eq!(
417	            editor_words(r"C:\Tools\vim.exe", true),
418	            Ok(vec![r"C:\Tools\vim.exe".to_owned()])
419	        );
420	        assert_eq!(
421	            editor_words(r#""C:\Program Files\Editor\ed.exe" --wait"#, true),
422	            Ok(vec![r"C:\Program Files\Editor\ed.exe".to_owned(), "--wait".to_owned()])
423	        );
424	        assert!(editor_words(r#""C:\open"#, true).is_err());
425	        assert_eq!(
426	            editor_words("code --wait", false),
427	            Ok(vec!["code".to_owned(), "--wait".to_owned()])
428	        );
429	    }
430	
431	    #[test]
432	    fn the_reason_for_an_ambiguous_word_says_how_to_pick_each() {
433	        // Rows: `2` then `1`; typing `1` could mean row 1 (package `2`) or the package named `1`.
434	        let listed = npm(&["2", "1"]);
435	        assert_eq!(
436	            choices("1", &listed).unwrap_err(),
437	            "`1` is both a package name and a row number; type `npm/1` for the package or `#1` for the row"
438	        );
439	        assert_eq!(choices("npm/1", &listed), Ok(vec![1]));
440	        assert_eq!(choices("#1", &listed), Ok(vec![0]));
441	        assert_eq!(choices("1-1", &listed), Ok(vec![0]));
442	        assert_eq!(choices("2-2", &listed), Ok(vec![1]));
443	        // A range collision names the rows as one `#` range.
444	        let error = choices("1-2", &npm(&["a", "b", "1-2"])).unwrap_err();
445	        assert!(
446	            error.ends_with("type `npm/1-2` for the package or `#1-2` for the row"),
447	            "{error}"
448	        );
449	    }
450	
451	    #[test]
452	    fn a_qualified_id_is_accepted_as_a_listed_name() {
453	        let listed = npm(&["a", "b"]);
454	        assert_eq!(choices("npm/b a", &listed), Ok(vec![0, 1]));
455	        assert!(choices("cargo/a", &listed).is_err());
456	    }
457	
458	    #[test]
459	    fn a_number_or_range_without_those_rows_is_matched_as_a_name() {
460	        assert_eq!(choices("42", &names(&["42"])), Ok(vec![0]));
461	        assert_eq!(choices("42", &names(&["a", "42"])), Ok(vec![1]));
462	        assert_eq!(choices("2-9", &names(&["a", "2-9"])), Ok(vec![1]));
463	        assert_eq!(choices("3-1", &names(&["a", "3-1"])), Ok(vec![1]));
464	        // The rows exist, so the number is a row.
465	        assert_eq!(choices("1", &names(&["42"])), Ok(vec![0]));
466	    }
467	
468	    #[test]
469	    fn an_empty_line_keeps_the_marked_ones_and_one_pick_needs_exactly_one() {
470	        let listed = names(&["a", "b", "c"]);
471	        assert_eq!(answer("  ", &listed, &[false, true, true], false), Ok(vec![1, 2]));
472	        assert_eq!(answer("", &listed, &[], false), Ok(vec![]));
473	        assert_eq!(answer("2", &listed, &[], true), Ok(vec![1]));
474	        for line in ["", "1 2", "1-2"] {
475	            assert_eq!(
476	                answer(line, &listed, &[], true),
477	                Err("pick exactly one".to_owned()),
478	                "{line:?}"
479	            );
480	        }
481	    }
482	}

