  1	//! The one contract for interactive prompts: where they may run, how they end, and how `$EDITOR` is used.
  2	
  3	use std::io::IsTerminal as _;
  4	
  5	use inquire::validator::Validation;
  6	use inquire::Text;
  7	
  8	use crate::cli::OutputFormat;
  9	use crate::error::CliError;
 10	
 11	/// Proof that this run may prompt; only [`Prompts::detect`] makes one.
 12	pub struct Prompts(());
 13	
 14	impl Prompts {
 15	    /// Prompts need a person at the terminal (stdin, and stderr where they draw) and a text run: `--format json` is for
 16	    /// scripts and never prompts.
 17	    pub fn detect(format: OutputFormat) -> Option<Self> {
 18	        (format == OutputFormat::Text && std::io::stdin().is_terminal() && std::io::stderr().is_terminal())
 19	            .then_some(Self(()))
 20	    }
 21	
 22	    #[cfg(test)]
 23	    pub fn for_tests() -> Self {
 24	        Self(())
 25	    }
 26	}
 27	
 28	/// Printed whenever a prompt run ends without writing.
 29	pub const CANCELLED: &str = "Cancelled, nothing written.";
 30	
 31	/// Exit status for a prompt cancelled with Esc or Ctrl-C: 130, as shells report SIGINT.
 32	pub const CANCELLED_EXIT: u8 = 130;
 33	
 34	/// A package in a list: the name the list shows, and its `ecosystem/name` id, which is also accepted when typed.
 35	#[derive(Clone, Debug, PartialEq, Eq)]
 36	pub(crate) struct Listed {
 37	    pub name: String,
 38	    pub id: String,
 39	}
 40	
 41	impl Listed {
 42	    /// An entry shown by its id.
 43	    pub fn by_id(id: &str) -> Self {
 44	        Self {
 45	            name: id.to_owned(),
 46	            id: id.to_owned(),
 47	        }
 48	    }
 49	}
 50	
 51	/// Asks which of `items` to pick, as `git add -i` does: the list is printed once, numbered, with `marked` ones starred,
 52	/// then one typed line answers. Nothing is redrawn, so no terminal size or resize can misdraw it. Enter keeps the marked
 53	/// ones (and, when `empty_ok`, picks none if none is marked); an answer that names nothing listed is asked again with
 54	/// the reason.
 55	pub(crate) fn pick_many(
 56	    heading: &str,
 57	    items: &[Listed],
 58	    marked: &[bool],
 59	    empty_ok: bool,
 60	) -> Result<Vec<usize>, CliError> {
 61	    print_list(heading, items, marked);
 62	    if marked.contains(&true) {
 63	        eprintln!("Enter keeps the * ones, or type numbers, ranges (1-3) or names; Esc cancels.");
 64	    } else if empty_ok {
 65	        eprintln!("Enter picks none, or type numbers, ranges (1-3) or names; Esc cancels.");
 66	    } else {
 67	        eprintln!("Type numbers, ranges (1-3) or names; Esc cancels.");
 68	    }
 69	    read_answer(items, marked, false)
 70	}
