 72	/// Asks for exactly one of `ids`, the way [`pick_many`] asks for several.
 73	pub(crate) fn pick_one(heading: &str, ids: &[String]) -> Result<usize, CliError> {
 74	    let items: Vec<Listed> = ids.iter().map(|id| Listed::by_id(id)).collect();
 75	    print_list(heading, &items, &[]);
 76	    eprintln!("Type a number or a name; Esc cancels.");
 77	    let picked = read_answer(&items, &[], true)?;
 78	    Ok(*picked
 79	        .first()
 80	        .expect("the validator accepts only an answer naming exactly one entry"))
 81	}
