 83	fn print_list(heading: &str, items: &[Listed], marked: &[bool]) {
 84	    let width = items.len().to_string().len();
 85	    let mut text = format!("{heading}\n");
 86	    for (index, item) in items.iter().enumerate() {
 87	        let mark = if marked.get(index) == Some(&true) { '*' } else { ' ' };
 88	        // A control character in a manifest's name must not drive the terminal.
 89	        text.push_str(&format!(
 90	            "  {:>width$} {mark} {}\n",
 91	            index + 1,
 92	            item.name.escape_debug()
 93	        ));
 94	    }
 95	    eprint!("{text}");
 96	}
