 98	/// One line typed at a single-line prompt; the prompt's validator asks again with the reason until [`answer`] accepts
 99	/// it, and Esc or Ctrl-C is [`CliError::Cancelled`].
100	fn read_answer(items: &[Listed], marked: &[bool], one: bool) -> Result<Vec<usize>, CliError> {
101	    let (valid_items, valid_marked) = (items.to_vec(), marked.to_vec());
102	    let line = Text::new("Your answer")
103	        .with_validator(move |line: &str| {
104	            Ok(match answer(line, &valid_items, &valid_marked, one) {
105	                Ok(_) => Validation::Valid,
106	                Err(reason) => Validation::Invalid(reason.into()),
107	            })
108	        })
109	        .prompt()?;
110	    Ok(answer(&line, items, marked, one).expect("the validator accepted this line"))
111	}
