113	/// The listed indices a typed line picks: the `marked` ones for an empty line (when several may be picked), else the
114	/// ones [`choices`] names; `one` requires exactly one.
115	fn answer(line: &str, items: &[Listed], marked: &[bool], one: bool) -> Result<Vec<usize>, String> {
116	    let picked = match (line.trim().is_empty(), one) {
117	        (true, false) => (0..items.len())
118	            .filter(|&index| marked.get(index) == Some(&true))
119	            .collect(),
120	        (true, true) => Vec::new(),
121	        (false, _) => choices(line, items)?,
122	    };
123	    if one && picked.len() != 1 {
124	        return Err("pick exactly one".to_owned());
125	    }
126	    Ok(picked)
127	}
