129	/// The listed indices an answer names, in list order. A word is a number or range counted from 1 (`3`, `1-3`) when
130	/// those rows exist, else a listed name or `ecosystem/name` id; `#3` or `#1-3` always means rows. Words are separated
131	/// by spaces or commas, and an answer must name at least one.
132	fn choices(answer: &str, items: &[Listed]) -> Result<Vec<usize>, String> {
133	    let mut picked = std::collections::BTreeSet::new();
134	    let mut words = 0;
135	    for word in answer
136	        .split(|c: char| c == ',' || c.is_whitespace())
137	        .filter(|word| !word.is_empty())
138	    {
139	        words += 1;
140	        let shown = word.escape_debug();
141	        if let Some(rows) = word.strip_prefix('#') {
142	            match numbered(rows, items.len()) {
143	                Some(range) => picked.extend(range?),
144	                None => return Err(format!("`{shown}` is not a row number or range")),
145	            }
146	            continue;
147	        }
148	        let by_name = items.iter().position(|item| item.name == word || item.id == word);
149	        let indices = match (by_name, numbered(word, items.len())) {
150	            (Some(index), None | Some(Err(_))) => index..=index,
151	            (Some(index), Some(Ok(range))) if range == (index..=index) => range,
152	            (Some(index), Some(Ok(range))) => {
153	                let rows = match (range.start(), range.end()) {
154	                    (first, last) if first == last => format!("#{}", first + 1),
155	                    (first, last) => format!("#{}-{}", first + 1, last + 1),
156	                };
157	                let id = &items[index].id;
158	                let package = if id == word {
159	                    format!("#{}", index + 1)
160	                } else {
161	                    id.escape_debug().to_string()
162	                };
163	                return Err(format!(
164	                    "`{shown}` is both a package name and a row number; type `{package}` for the package or `{rows}` for the row"
165	                ));
166	            }
167	            (None, Some(range)) => range?,
168	            (None, None) => return Err(format!("`{shown}` is not a number, a range or a listed name")),
169	        };
170	        picked.extend(indices);
171	    }
172	    if words == 0 {
173	        return Err("type at least one number, range or name".to_owned());
174	    }
175	    Ok(picked.into_iter().collect())
176	}
