178	/// `n` or `a-b`, counted from 1, as indices; `None` when the word is shaped like neither, `Some(Err)` when the rows are
179	/// not in the list.
180	fn numbered(word: &str, len: usize) -> Option<Result<std::ops::RangeInclusive<usize>, String>> {
181	    let (first, last) = word.split_once('-').unwrap_or((word, word));
182	    let digits = |text: &str| !text.is_empty() && text.bytes().all(|byte| byte.is_ascii_digit());
183	    if !digits(first) || !digits(last) {
184	        return None;
185	    }
186	    let listed = |text: &str| text.parse::<usize>().ok().filter(|number| (1..=len).contains(number));
187	    Some(match (listed(first), listed(last)) {
188	        (Some(low), Some(high)) if low <= high => Ok(low - 1..=high - 1),
189	        (Some(_), Some(_)) => Err(format!("`{word}` runs backwards; put the lower number first")),
190	        _ => Err(format!("`{word}` is not in the list (1-{len})")),
191	    })
192	}
