194	/// The editor named by `$VISUAL`, else `$EDITOR`.
195	pub struct Editor {
196	    variable: &'static str,
197	    command: String,
198	}
199	
200	/// Why the editor could not be used; its message is the warning to print.
201	#[derive(Debug, thiserror::Error)]
202	#[error("cannot use ${variable} (`{command}`): {reason}; asking for the summary here instead")]
203	pub struct EditorUnusable {
204	    variable: &'static str,
205	    command: String,
206	    reason: String,
207	}
208	
209	impl Editor {
210	    /// An empty or blank setting is unset.
211	    pub fn from_env() -> Option<Self> {
212	        ["VISUAL", "EDITOR"].into_iter().find_map(|variable| {
213	            let command = std::env::var(variable).ok()?;
214	            (!command.trim().is_empty()).then_some(Self { variable, command })
215	        })
216	    }
217	
218	    /// `VISUAL` or `EDITOR`, whichever named it.
219	    pub fn variable(&self) -> &'static str {
220	        self.variable
221	    }
222	
223	    /// Opens the editor on an empty file and returns what was saved. `None` when the editor exits non-zero (an abort,
224	    /// as `:cq` in Vim). The editor draws on stderr so stdout stays for the report.
225	    pub fn edit(self) -> Result<Option<String>, EditorUnusable> {
226	        self.try_edit().map_err(|reason| EditorUnusable {
227	            variable: self.variable,
228	            command: self.command,
229	            reason,
230	        })
231	    }
232	
233	    fn try_edit(&self) -> Result<Option<String>, String> {
234	        let words = editor_words(&self.command, cfg!(windows))?;
235	        let Some((program, args)) = words.split_first() else {
236	            return Err("it names no program".to_owned());
237	        };
238	        let failed = |error: std::io::Error| error.to_string();
239	        let file = tempfile::Builder::new()
240	            .prefix("callisto-")
241	            .suffix(".txt")
242	            .tempfile()
243	            .map_err(failed)?;
244	        let _editor_owns_ctrl_c = editor_owns_ctrl_c::enter().map_err(failed)?;
245	        let status = crate::runner::child_command(program, &[], &[])
246	            .args(args)
247	            .arg(file.path())
248	            .stdout(std::io::stderr())
249	            .status()
250	            .map_err(|error| format!("`{program}` did not start: {error}"))?;
251	        if !status.success() {
252	            return Ok(None);
253	        }
254	        let saved = std::fs::read(file.path()).map_err(failed)?;
255	        String::from_utf8(saved)
256	            .map(Some)
257	            .map_err(|error| format!("what it saved is not UTF-8 text: {}", error.utf8_error()))
258	    }
259	}
