261	/// The program and arguments an editor setting names. Unix settings follow shell quoting; Windows paths use
262	/// backslashes as separators, so there a setting splits on whitespace outside double quotes and keeps every backslash.
263	fn editor_words(command: &str, windows: bool) -> Result<Vec<String>, String> {
264	    if !windows {
265	        return shell_words::split(command).map_err(|error| format!("it does not split into words: {error}"));
266	    }
267	    let mut words = Vec::new();
268	    let (mut word, mut quoted, mut started) = (String::new(), false, false);
269	    for c in command.chars() {
270	        match c {
271	            '"' => (quoted, started) = (!quoted, true),
272	            c if c.is_whitespace() && !quoted => {
273	                if started {
274	                    words.push(std::mem::take(&mut word));
275	                }
276	                started = false;
277	            }
278	            c => {
279	                word.push(c);
280	                started = true;
281	            }
282	        }
283	    }
284	    if quoted {
285	        return Err("it does not split into words: a double quote is not closed".to_owned());
286	    }
287	    if started {
288	        words.push(word);
289	    }
290	    Ok(words)
291	}
