157	/// The wizard's questions; a scripted implementation drives tests. Esc or Ctrl-C at any of them is
158	/// [`CliError::Cancelled`].
159	trait AddPrompter {
160	    /// The indices of the packages the contributor picked; `marked` ones are picked when they just press Enter.
161	    fn pick(
162	        &mut self,
163	        heading: &str,
164	        items: &[Listed],
165	        marked: &[bool],
166	        empty_ok: bool,
167	    ) -> Result<Vec<usize>, CliError>;
168	    /// The summary; an empty answer opens `$EDITOR` for a longer one. `None` when the editor saves nothing.
169	    fn summary(&mut self, prompt: &str) -> Result<Option<Summary>, CliError>;
170	    fn confirm(&mut self, prompt: &str, default: bool) -> Result<bool, CliError>;
171	}
172	
173	struct TerminalAddPrompter {
174	    _allowed: tty::Prompts,
175	}
176	
177	impl AddPrompter for TerminalAddPrompter {
178	    fn pick(
179	        &mut self,
180	        heading: &str,
181	        items: &[Listed],
182	        marked: &[bool],
183	        empty_ok: bool,
184	    ) -> Result<Vec<usize>, CliError> {
185	        tty::pick_many(heading, items, marked, empty_ok)
186	    }
187	
188	    fn summary(&mut self, prompt: &str) -> Result<Option<Summary>, CliError> {
189	        let mut editor = tty::Editor::from_env();
190	        loop {
191	            let hint = match &editor {
192	                Some(editor) => format!("{prompt} (leave empty to open ${}; Esc cancels)", editor.variable()),
193	                None => format!("{prompt} (Esc cancels)"),
194	            };
195	            let opens_editor = editor.is_some();
196	            let line = Text::new(&hint)
197	                .with_validator(move |line: &str| {
198	                    Ok(match Summary::new(line) {
199	                        Err(_) if !(opens_editor && line.is_empty()) => {
200	                            Validation::Invalid("the summary cannot be blank".into())
201	                        }
202	                        _ => Validation::Valid,
203	                    })
204	                })
205	                .prompt()?;
206	            if let Ok(summary) = Summary::new(&line) {
207	                return Ok(Some(summary));
208	            }
209	            // The validator lets an empty line through only when there is an editor to open.
210	            let Some(chosen) = editor.take() else { continue };
211	            match chosen.edit() {
212	                Ok(saved) => return Ok(saved.and_then(|text| Summary::new(&text).ok())),
213	                // The answers so far are kept: the summary is asked for inline instead.
214	                Err(unusable) => prompt_line(&format!("warning: {unusable}")),
215	            }
216	        }
217	    }
218	
219	    fn confirm(&mut self, prompt: &str, default: bool) -> Result<bool, CliError> {
220	        Ok(Confirm::new(prompt).with_default(default).prompt()?)
221	    }
222	}
