224	/// A package the wizard offers, and whether it changed since its last tag.
225	struct Choice {
226	    item: Listed,
227	    changed: bool,
228	}
229	
230	/// The interactive wizard (as in `@changesets/cli`): packages, which are major, which of the rest are minor (the
231	/// remainder default to patch), a summary unless one was given, then a review to confirm (a dry run writes nothing, so
232	/// it does not ask). Changed packages are listed
233	/// first and marked, so Enter picks them. `None` when the contributor declines the review or the editor saves nothing, having been
234	/// told nothing was written.
235	fn run_wizard(
236	    choices: &[Choice],
237	    summary: Option<Summary>,
238	    dry_run: bool,
239	    prompter: &mut impl AddPrompter,
240	) -> Result<Option<(Vec<Entry>, Summary)>, CliError> {
241	    let answers = ask(choices, summary, dry_run, prompter)?;
242	    if answers.is_none() {
243	        prompt_line(tty::CANCELLED);
244	    }
245	    Ok(answers)
246	}
247	
248	fn ask(
249	    choices: &[Choice],
250	    summary: Option<Summary>,
251	    dry_run: bool,
252	    prompter: &mut impl AddPrompter,
253	) -> Result<Option<(Vec<Entry>, Summary)>, CliError> {
254	    if choices.is_empty() {
255	        return Err(CliError::AddNoPackagesInWorkspace);
256	    }
257	
258	    let mut ordered: Vec<&Choice> = choices.iter().collect();
259	    ordered.sort_by_key(|choice| !choice.changed);
260	    let items: Vec<Listed> = ordered.iter().map(|choice| choice.item.clone()).collect();
261	    let changed: Vec<bool> = ordered.iter().map(|choice| choice.changed).collect();
262	    let selected_indices = prompter.pick(
263	        "Packages in this change (* changed since its last release):",
264	        &items,
265	        &changed,
266	        false,
267	    )?;
268	    if selected_indices.is_empty() {
269	        return Err(CliError::AddNoPackagesSelected);
270	    }
271	    let selected_packages: Vec<Listed> = selected_indices.into_iter().map(|i| items[i].clone()).collect();
272	    let unmarked = vec![false; selected_packages.len()];
273	
274	    let majors = prompter.pick(
275	        "Which are a MAJOR bump? (breaking changes only)",
276	        &selected_packages,
277	        &unmarked,
278	        true,
279	    )?;
280	    let major_set: std::collections::HashSet<usize> = majors.into_iter().collect();
281	
282	    let minor_candidates: Vec<Listed> = selected_packages
283	        .iter()
284	        .enumerate()
285	        .filter(|(idx, _)| !major_set.contains(idx))
286	        .map(|(_, item)| item.clone())
287	        .collect();
288	    let minor_set: std::collections::HashSet<String> = if minor_candidates.is_empty() {
289	        std::collections::HashSet::new()
290	    } else {
291	        let minors = prompter.pick(
292	            "Which are a MINOR bump? (the rest get PATCH)",
293	            &minor_candidates,
294	            &unmarked[..minor_candidates.len()],
295	            true,
296	        )?;
297	        minors
298	            .into_iter()
299	            .map(|idx| minor_candidates[idx].name.clone())
300	            .collect()
301	    };
302	
303	    let entries: Vec<Entry> = selected_packages
304	        .iter()
305	        .enumerate()
306	        .map(|(idx, item)| Entry {
307	            name: item.name.clone(),
308	            severity: if major_set.contains(&idx) {
309	                Severity::Major
310	            } else if minor_set.contains(&item.name) {
311	                Severity::Minor
312	            } else {
313	                Severity::Patch
314	            },
315	        })
316	        .collect();
317	
318	    let summary = match summary {
319	        Some(summary) => summary,
320	        None => match prompter.summary("Changelog summary")? {
321	            Some(summary) => summary,
322	            None => return Ok(None),
323	        },
324	    };
325	
326	    prompt_line(&review(&entries, &summary.0));
327	    if dry_run || prompter.confirm("Write this changeset?", true)? {
328	        Ok(Some((entries, summary)))
329	    } else {
330	        Ok(None)
331	    }
332	}
