334	/// What the changeset will record: each package's bump, then the summary as it reaches the changelog.
335	fn review(entries: &[Entry], summary: &str) -> String {
336	    let mut text = String::from("\nThis changeset records:\n");
337	    for entry in entries {
338	        // A control character in a manifest's name must not drive the terminal.
339	        text.push_str(&format!(
340	            "  {:<5}  {}\n",
341	            entry.severity.to_string(),
342	            entry.name.escape_debug()
343	        ));
344	    }
345	    text.push('\n');
346	    for line in summary.trim().lines() {
347	        text.push_str(&format!("  {line}\n"));
348	    }
349	    text
350	}
