361	/// The wizard's packages, named by `.display_name()` so `cargo/foo` and `npm/foo` stay distinct in a polyglot workspace.
362	/// When the changed packages cannot be worked out, says so once and offers every package unpicked.
363	fn wizard_choices<'a>(
364	    packages: impl Iterator<Item = &'a callisto_model::Package>,
365	    changed: Result<std::collections::BTreeMap<callisto_model::PackageId, bool>, callisto_graph::GraphError>,
366	) -> Vec<Choice> {
367	    let changed = changed.unwrap_or_else(|error| {
368	        prompt_line(&format!(
369	            "warning: could not tell which packages changed since their last release, so none is picked: {error}"
370	        ));
371	        std::collections::BTreeMap::new()
372	    });
373	    packages
374	        .map(|pkg| Choice {
375	            item: Listed {
376	                name: pkg.id.display_name(),
377	                id: pkg.canonical_id().display_name(),
378	            },
379	            changed: changed.get(&pkg.id).copied().unwrap_or(false),
380	        })
381	        .collect()
382	}
