142	142	/// A changeset summary: trimmed, with LF line ends, and never blank, whichever way it was supplied.
143	143	#[derive(Clone, Debug, PartialEq, Eq)]
144	144	struct Summary(String);
145	145	
146	146	impl Summary {
147	147	    /// A leading byte-order mark (some editors save one) is dropped and CRLF line ends become LF.
148	148	    fn new(text: &str) -> Result<Self, CliError> {
149	149	        let trimmed = text.trim_start_matches('\u{feff}').trim();
150	150	        if trimmed.is_empty() {
151	151	            return Err(CliError::AddSummaryEmpty);
152	152	        }
153	153	        Ok(Self(trimmed.replace("\r\n", "\n")))
154	154	    }
155	155	}
156	156	
157	157	/// The wizard's questions; a scripted implementation drives tests. Esc or Ctrl-C at any of them is
158	158	/// [`CliError::Cancelled`].
159	159	trait AddPrompter {
160	160	    /// The indices of the packages the contributor picked; `marked` ones are picked when they just press Enter.
161	161	    fn pick(
162	162	        &mut self,
163	163	        heading: &str,
164	164	        items: &[Listed],
165	165	        marked: &[bool],
166	166	        empty_ok: bool,
167	167	    ) -> Result<Vec<usize>, CliError>;
168	168	    /// The summary; an empty answer opens `$EDITOR` for a longer one. `None` when the editor saves nothing.
169	169	    fn summary(&mut self, prompt: &str) -> Result<Option<Summary>, CliError>;
170	170	    fn confirm(&mut self, prompt: &str, default: bool) -> Result<bool, CliError>;
171	171	}
172	172	
173	173	struct TerminalAddPrompter {
174	174	    _allowed: tty::Prompts,
175	175	}
176	176	
177	177	impl AddPrompter for TerminalAddPrompter {
178	178	    fn pick(
179	179	        &mut self,
180	180	        heading: &str,
181	181	        items: &[Listed],
182	182	        marked: &[bool],
183	183	        empty_ok: bool,
184	184	    ) -> Result<Vec<usize>, CliError> {
185	185	        tty::pick_many(heading, items, marked, empty_ok)
186	186	    }
187	187	
188	188	    fn summary(&mut self, prompt: &str) -> Result<Option<Summary>, CliError> {
189	189	        let mut editor = tty::Editor::from_env();
190	190	        loop {
191	191	            let hint = match &editor {
192	192	                Some(editor) => format!("{prompt} (leave empty to open ${}; Esc cancels)", editor.variable()),
193	193	                None => format!("{prompt} (Esc cancels)"),
194	194	            };
195	195	            let opens_editor = editor.is_some();
196	196	            let line = Text::new(&hint)
197	197	                .with_validator(move |line: &str| {
198	198	                    Ok(match Summary::new(line) {
199	199	                        Err(_) if !(opens_editor && line.is_empty()) => {
200	200	                            Validation::Invalid("the summary cannot be blank".into())
201	201	                        }
202	202	                        _ => Validation::Valid,
203	203	                    })
204	204	                })
205	205	                .prompt()?;
206	206	            if let Ok(summary) = Summary::new(&line) {
207	207	                return Ok(Some(summary));
208	208	            }
209	209	            // The validator lets an empty line through only when there is an editor to open.
210	210	            let Some(chosen) = editor.take() else { continue };
211	211	            match chosen.edit() {
212	212	                Ok(saved) => return Ok(saved.and_then(|text| Summary::new(&text).ok())),
213	213	                // The answers so far are kept: the summary is asked for inline instead.
214	214	                Err(unusable) => prompt_line(&format!("warning: {unusable}")),
215	215	            }
216	216	        }
217	217	    }
218	218	
219	219	    fn confirm(&mut self, prompt: &str, default: bool) -> Result<bool, CliError> {
220	220	        Ok(Confirm::new(prompt).with_default(default).prompt()?)
221	221	    }
222	222	}
223	223	
224	224	/// A package the wizard offers, and whether it changed since its last tag.
225	225	struct Choice {
226	226	    item: Listed,
227	227	    changed: bool,
228	228	}
229	229	
230	230	/// The interactive wizard (as in `@changesets/cli`): packages, which are major, which of the rest are minor (the
231	231	/// remainder default to patch), a summary unless one was given, then a review to confirm (a dry run writes nothing, so
232	232	/// it does not ask). Changed packages are listed
233	233	/// first and marked, so Enter picks them. `None` when the contributor declines the review or the editor saves nothing, having been
234	234	/// told nothing was written.
235	235	fn run_wizard(
236	236	    choices: &[Choice],
237	237	    summary: Option<Summary>,
238	238	    dry_run: bool,
239	239	    prompter: &mut impl AddPrompter,
240	240	) -> Result<Option<(Vec<Entry>, Summary)>, CliError> {
241	241	    let answers = ask(choices, summary, dry_run, prompter)?;
242	242	    if answers.is_none() {
243	243	        prompt_line(tty::CANCELLED);
244	244	    }
245	245	    Ok(answers)
246	246	}
247	247	
248	248	fn ask(
249	249	    choices: &[Choice],
250	250	    summary: Option<Summary>,
251	251	    dry_run: bool,
252	252	    prompter: &mut impl AddPrompter,
253	253	) -> Result<Option<(Vec<Entry>, Summary)>, CliError> {
254	254	    if choices.is_empty() {
255	255	        return Err(CliError::AddNoPackagesInWorkspace);
256	256	    }
257	257	
258	258	    let mut ordered: Vec<&Choice> = choices.iter().collect();
259	259	    ordered.sort_by_key(|choice| !choice.changed);
260	260	    let items: Vec<Listed> = ordered.iter().map(|choice| choice.item.clone()).collect();
261	261	    let changed: Vec<bool> = ordered.iter().map(|choice| choice.changed).collect();
262	262	    let selected_indices = prompter.pick(
263	263	        "Packages in this change (* changed since its last release):",
264	264	        &items,
265	265	        &changed,
266	266	        false,
267	267	    )?;
268	268	    if selected_indices.is_empty() {
269	269	        return Err(CliError::AddNoPackagesSelected);
270	270	    }
271	271	    let selected_packages: Vec<Listed> = selected_indices.into_iter().map(|i| items[i].clone()).collect();
272	272	    let unmarked = vec![false; selected_packages.len()];
273	273	
274	274	    let majors = prompter.pick(
275	275	        "Which are a MAJOR bump? (breaking changes only)",
276	276	        &selected_packages,
277	277	        &unmarked,
278	278	        true,
279	279	    )?;
280	280	    let major_set: std::collections::HashSet<usize> = majors.into_iter().collect();
281	281	
282	282	    let minor_candidates: Vec<Listed> = selected_packages
283	283	        .iter()
284	284	        .enumerate()
285	285	        .filter(|(idx, _)| !major_set.contains(idx))
286	286	        .map(|(_, item)| item.clone())
287	287	        .collect();
288	288	    let minor_set: std::collections::HashSet<String> = if minor_candidates.is_empty() {
289	289	        std::collections::HashSet::new()
290	290	    } else {
291	291	        let minors = prompter.pick(
292	292	            "Which are a MINOR bump? (the rest get PATCH)",
293	293	            &minor_candidates,
294	294	            &unmarked[..minor_candidates.len()],
295	295	            true,
296	296	        )?;
297	297	        minors
298	298	            .into_iter()
299	299	            .map(|idx| minor_candidates[idx].name.clone())
300	300	            .collect()
301	301	    };
302	302	
303	303	    let entries: Vec<Entry> = selected_packages
304	304	        .iter()
305	305	        .enumerate()
306	306	        .map(|(idx, item)| Entry {
307	307	            name: item.name.clone(),
308	308	            severity: if major_set.contains(&idx) {
309	309	                Severity::Major
310	310	            } else if minor_set.contains(&item.name) {
311	311	                Severity::Minor
312	312	            } else {
313	313	                Severity::Patch
314	314	            },
315	315	        })
316	316	        .collect();
317	317	
318	318	    let summary = match summary {
319	319	        Some(summary) => summary,
320	320	        None => match prompter.summary("Changelog summary")? {
321	321	            Some(summary) => summary,
322	322	            None => return Ok(None),
323	323	        },
324	324	    };
325	325	
326	326	    prompt_line(&review(&entries, &summary.0));
327	327	    if dry_run || prompter.confirm("Write this changeset?", true)? {
328	328	        Ok(Some((entries, summary)))
329	329	    } else {
330	330	        Ok(None)
331	331	    }
332	332	}
333	333	
334	334	/// What the changeset will record: each package's bump, then the summary as it reaches the changelog.
335	335	fn review(entries: &[Entry], summary: &str) -> String {
336	336	    let mut text = String::from("\nThis changeset records:\n");
337	337	    for entry in entries {
338	338	        // A control character in a manifest's name must not drive the terminal.
339	339	        text.push_str(&format!(
340	340	            "  {:<5}  {}\n",
341	341	            entry.severity.to_string(),
342	342	            entry.name.escape_debug()
343	343	        ));
344	344	    }
345	345	    text.push('\n');
346	346	    for line in summary.trim().lines() {
347	347	        text.push_str(&format!("  {line}\n"));
348	348	    }
349	349	    text
350	350	}
351	351	
352	352	/// Parses a CLI-supplied severity string, reporting every value `Severity`
353	353	/// actually accepts (`none`, `patch`, `minor`, `major`) on failure -- not a
354	354	/// stale subset that omits `none`.
355	355	fn parse_severity(sev_str: &str) -> Result<Severity, CliError> {
356	356	    sev_str.parse().map_err(|_err| CliError::InvalidSeverity {
357	357	        value: sev_str.to_string(),
358	358	    })
359	359	}
360	360	
361	361	/// The wizard's packages, named by `.display_name()` so `cargo/foo` and `npm/foo` stay distinct in a polyglot workspace.
362	362	/// When the changed packages cannot be worked out, says so once and offers every package unpicked.
363	363	fn wizard_choices<'a>(
364	364	    packages: impl Iterator<Item = &'a callisto_model::Package>,
365	365	    changed: Result<std::collections::BTreeMap<callisto_model::PackageId, bool>, callisto_graph::GraphError>,
366	366	) -> Vec<Choice> {
367	367	    let changed = changed.unwrap_or_else(|error| {
368	368	        prompt_line(&format!(
369	369	            "warning: could not tell which packages changed since their last release, so none is picked: {error}"
370	370	        ));
371	371	        std::collections::BTreeMap::new()
372	372	    });
373	373	    packages
374	374	        .map(|pkg| Choice {
375	375	            item: Listed {
376	376	                name: pkg.id.display_name(),
377	377	                id: pkg.canonical_id().display_name(),
378	378	            },
379	379	            changed: changed.get(&pkg.id).copied().unwrap_or(false),
380	380	        })
381	381	        .collect()
382	382	}
383	383	
384	384	/// Writes `text` to a new file in `dir` named by `next_slug`, trying another slug whenever the name is taken, including
385	385	/// by a changeset another process created after this one looked. Nothing already in `dir` is ever replaced.
386	386	fn create_changeset(
387	387	    dir: &std::path::Path,
388	388	    archive: &std::path::Path,
389	389	    text: &str,
390	390	    permit: &ApplyPermit,
391	391	    mut next_slug: impl FnMut() -> String,
392	392	) -> Result<String, CliError> {
393	393	    // 8,000 possible slugs: more than a few attempts only happens when nearly all of them are taken.
394	394	    for _ in 0..64 {
395	395	        let filename = format!("{}.md", next_slug());
396	396	        if archived(archive, &filename)? {
397	397	            continue;
398	398	        }
399	399	        let path = dir.join(&filename);
400	400	        match callisto_model::atomic::atomic_write_new(&path, text, permit) {
401	401	            Ok(()) => return Ok(filename),
402	402	            Err(error) if error.kind() == std::io::ErrorKind::AlreadyExists => {}
403	403	            Err(source) => {
404	404	                return Err(CliError::Io {
405	405	                    source,
406	406	                    path: Some(path),
407	407	                })
408	408	            }
409	409	        }
410	410	    }
411	411	    Err(CliError::Io {
412	412	        source: std::io::Error::new(
413	413	            std::io::ErrorKind::AlreadyExists,
414	414	            "no unused changeset filename found after 64 attempts",
415	415	        ),
416	416	        path: Some(dir.to_path_buf()),
417	417	    })
418	418	}
419	419	
420	420	/// Whether a Changesets v3 pre cycle archived a note under `filename`; a new note there would read as its duplicate.
421	421	fn archived(archive: &std::path::Path, filename: &str) -> Result<bool, CliError> {
422	422	    let path = archive.join(filename);
423	423	    callisto_model::strict_fs::exists(&path).map_err(|source| CliError::Io {
424	424	        source,
425	425	        path: Some(path),
426	426	    })
427	427	}
428	428	
429	429	/// Picks a changeset filename that does not exist yet, so a slug collision never overwrites a pending changeset.
430	430	fn unused_changeset_filename(dir: &std::path::Path, archive: &std::path::Path) -> Result<String, CliError> {
431	431	    // 8,000 possible slugs: more than a few attempts only happens when nearly all of them are taken.
432	432	    for _ in 0..64 {
433	433	        let filename = format!("{}.md", generate_human_slug());
434	434	        let path = dir.join(&filename);
435	435	        let taken = callisto_model::strict_fs::exists(&path).map_err(|source| CliError::Io {
436	436	            source,
437	437	            path: Some(path.clone()),
438	438	        })?;
439	439	        if !taken && !archived(archive, &filename)? {
440	440	            return Ok(filename);
441	441	        }
442	442	    }
443	443	    Err(CliError::Io {
444	444	        source: std::io::Error::new(
445	445	            std::io::ErrorKind::AlreadyExists,
446	446	            "no unused changeset filename found after 64 attempts",
447	447	        ),
448	448	        path: Some(dir.to_path_buf()),
449	449	    })
450	450	}
451	451	
452	452	fn generate_human_slug() -> String {
453	453	    use std::sync::atomic::{AtomicU64, Ordering};
454	454	
455	455	    static COUNTER: AtomicU64 = AtomicU64::new(0);
456	456	
457	457	    let adjectives = [
458	458	        "swift", "clever", "bright", "silent", "brave", "calm", "eager", "gentle", "happy", "jolly", "keen", "lively",
459	459	        "mighty", "noble", "proud", "quick", "radiant", "sharp", "tough", "vivid",
460	460	    ];
461	461	    let nouns = [
462	462	        "foxes", "hawks", "wolves", "eagles", "bears", "lions", "otters", "pandas", "falcons", "tigers", "dolphins",
463	463	        "panthers", "cheetahs", "leopards", "ravens", "badgers", "lynxes", "cobras", "owls", "stags",
464	464	    ];
465	465	    let verbs = [
466	466	        "run", "fly", "leap", "soar", "dash", "hunt", "glide", "climb", "swim", "roar", "pounce", "sprint", "chase",
467	467	        "race", "bound", "drift", "jump", "strut", "spin", "surge",
468	468	    ];
469	469	
470	470	    // Each word list has 20 entries; consecutive counter values map to unique triples (a = idx % 20, n = (idx / 20) % 20,
471	471	    // v = (idx / 400) % 20), a bijection on 0..7999. A timestamp-derived offset varies the start across process restarts.
472	472	    let ts = std::time::SystemTime::now()
473	473	        .duration_since(std::time::UNIX_EPOCH)
474	474	        .map(|d| d.as_nanos() as u64)
475	475	        .unwrap_or(0);
476	476	
477	477	    let count = COUNTER.fetch_add(1, Ordering::Relaxed);
478	478	    // Shift ts right to get a slowly-varying cross-run offset (changes every ~1 µs).
479	479	    let offset = (ts >> 10) % 8000;
480	480	    let idx = (count + offset) % 8000;
481	481	
482	482	    let a = adjectives[(idx % 20) as usize];
483	483	    let n = nouns[((idx / 20) % 20) as usize];
484	484	    let v = verbs[((idx / 400) % 20) as usize];
485	485	
486	486	    format!("{a}-{n}-{v}")
487	487	}
