142	/// A changeset summary: trimmed, with LF line ends, and never blank, whichever way it was supplied.
143	#[derive(Clone, Debug, PartialEq, Eq)]
144	struct Summary(String);
145	
146	impl Summary {
147	    /// A leading byte-order mark (some editors save one) is dropped and CRLF line ends become LF.
148	    fn new(text: &str) -> Result<Self, CliError> {
149	        let trimmed = text.trim_start_matches('\u{feff}').trim();
150	        if trimmed.is_empty() {
151	            return Err(CliError::AddSummaryEmpty);
152	        }
153	        Ok(Self(trimmed.replace("\r\n", "\n")))
154	    }
155	}
