352	/// Parses a CLI-supplied severity string, reporting every value `Severity`
353	/// actually accepts (`none`, `patch`, `minor`, `major`) on failure -- not a
354	/// stale subset that omits `none`.
355	fn parse_severity(sev_str: &str) -> Result<Severity, CliError> {
356	    sev_str.parse().map_err(|_err| CliError::InvalidSeverity {
357	        value: sev_str.to_string(),
358	    })
359	}
