384	/// Writes `text` to a new file in `dir` named by `next_slug`, trying another slug whenever the name is taken, including
385	/// by a changeset another process created after this one looked. Nothing already in `dir` is ever replaced.
386	fn create_changeset(
387	    dir: &std::path::Path,
388	    archive: &std::path::Path,
389	    text: &str,
390	    permit: &ApplyPermit,
391	    mut next_slug: impl FnMut() -> String,
392	) -> Result<String, CliError> {
393	    // 8,000 possible slugs: more than a few attempts only happens when nearly all of them are taken.
394	    for _ in 0..64 {
395	        let filename = format!("{}.md", next_slug());
396	        if archived(archive, &filename)? {
397	            continue;
398	        }
399	        let path = dir.join(&filename);
400	        match callisto_model::atomic::atomic_write_new(&path, text, permit) {
401	            Ok(()) => return Ok(filename),
402	            Err(error) if error.kind() == std::io::ErrorKind::AlreadyExists => {}
403	            Err(source) => {
404	                return Err(CliError::Io {
405	                    source,
406	                    path: Some(path),
407	                })
408	            }
409	        }
410	    }
411	    Err(CliError::Io {
412	        source: std::io::Error::new(
413	            std::io::ErrorKind::AlreadyExists,
414	            "no unused changeset filename found after 64 attempts",
415	        ),
416	        path: Some(dir.to_path_buf()),
417	    })
418	}
419	
420	/// Whether a Changesets v3 pre cycle archived a note under `filename`; a new note there would read as its duplicate.
421	fn archived(archive: &std::path::Path, filename: &str) -> Result<bool, CliError> {
422	    let path = archive.join(filename);
423	    callisto_model::strict_fs::exists(&path).map_err(|source| CliError::Io {
424	        source,
425	        path: Some(path),
426	    })
427	}
428	
429	/// Picks a changeset filename that does not exist yet, so a slug collision never overwrites a pending changeset.
430	fn unused_changeset_filename(dir: &std::path::Path, archive: &std::path::Path) -> Result<String, CliError> {
431	    // 8,000 possible slugs: more than a few attempts only happens when nearly all of them are taken.
432	    for _ in 0..64 {
433	        let filename = format!("{}.md", generate_human_slug());
434	        let path = dir.join(&filename);
435	        let taken = callisto_model::strict_fs::exists(&path).map_err(|source| CliError::Io {
436	            source,
437	            path: Some(path.clone()),
438	        })?;
439	        if !taken && !archived(archive, &filename)? {
440	            return Ok(filename);
441	        }
442	    }
443	    Err(CliError::Io {
444	        source: std::io::Error::new(
445	            std::io::ErrorKind::AlreadyExists,
446	            "no unused changeset filename found after 64 attempts",
447	        ),
448	        path: Some(dir.to_path_buf()),
449	    })
450	}
451	
452	fn generate_human_slug() -> String {
453	    use std::sync::atomic::{AtomicU64, Ordering};
454	
455	    static COUNTER: AtomicU64 = AtomicU64::new(0);
456	
457	    let adjectives = [
458	        "swift", "clever", "bright", "silent", "brave", "calm", "eager", "gentle", "happy", "jolly", "keen", "lively",
459	        "mighty", "noble", "proud", "quick", "radiant", "sharp", "tough", "vivid",
460	    ];
461	    let nouns = [
462	        "foxes", "hawks", "wolves", "eagles", "bears", "lions", "otters", "pandas", "falcons", "tigers", "dolphins",
463	        "panthers", "cheetahs", "leopards", "ravens", "badgers", "lynxes", "cobras", "owls", "stags",
464	    ];
465	    let verbs = [
466	        "run", "fly", "leap", "soar", "dash", "hunt", "glide", "climb", "swim", "roar", "pounce", "sprint", "chase",
467	        "race", "bound", "drift", "jump", "strut", "spin", "surge",
468	    ];
469	
470	    // Each word list has 20 entries; consecutive counter values map to unique triples (a = idx % 20, n = (idx / 20) % 20,
471	    // v = (idx / 400) % 20), a bijection on 0..7999. A timestamp-derived offset varies the start across process restarts.
472	    let ts = std::time::SystemTime::now()
473	        .duration_since(std::time::UNIX_EPOCH)
474	        .map(|d| d.as_nanos() as u64)
475	        .unwrap_or(0);
476	
477	    let count = COUNTER.fetch_add(1, Ordering::Relaxed);
478	    // Shift ts right to get a slowly-varying cross-run offset (changes every ~1 µs).
479	    let offset = (ts >> 10) % 8000;
480	    let idx = (count + offset) % 8000;
481	
482	    let a = adjectives[(idx % 20) as usize];
483	    let n = nouns[((idx / 20) % 20) as usize];
484	    let v = verbs[((idx / 400) % 20) as usize];
485	
486	    format!("{a}-{n}-{v}")
487	}
